// mysql_guard — separa caso OK / caso error del nodo MySQL

function fail(reason) {
    msg.payload = {
        answer: '❌ Error al ejecutar la consulta SQL en la base de datos: ' + reason,
        columns: [],
        rows: [],
        sql: msg.sql || msg.topic || '',
        via: msg.via || 'web',
        suggestions: [
            'Revisa que los nombres de las columnas sean correctos (por ejemplo L en lugar de Luz).',
            'Reformula la pregunta con más detalle.'
        ]
    };
    return [null, msg]; // salida 2 -> HTTP response
}

// Caso error explícito: msg.error
if (msg.error) {
    return fail(msg.error.message || String(msg.error));
}

// Caso error: payload es un Error o algo raro
if (msg.payload instanceof Error) {
    return fail(msg.payload.message || String(msg.payload));
}

// ⚠️ Si el payload NO es un array (lo normal del nodo MySQL),
// lo tratamos como error genérico.
if (!Array.isArray(msg.payload)) {
    const p = msg.payload || {};
    const reason = p.sqlMessage || p.message || JSON.stringify(p);
    return fail(reason);
}

// Caso OK: msg.payload son filas de la DB (array)
return [msg, null];

// Lee identidad desde variables de entorno (con defaults seguros)
const NAME     = env.get('ABOUT_NAME')     || 'QUILLAMA';
const VERSION  = env.get('ABOUT_VERSION')  || '0.1.0';
const OWNER    = env.get('ABOUT_OWNER')    || 'Quillaqua';
const MISSION  = (env.get('ABOUT_MISSION') || 'Analista de clima para invernaderos. Resumo, detecto anomalías y doy recomendaciones operativas basadas en lecturas SQL.').trim();
const TONE     = (env.get('ABOUT_TONE')    || 'Claro, breve y accionable.').trim();
const GUARDS   = (env.get('ABOUT_GUARDS')  || 'No invento valores. Uso solo datos del SQL. Si no hay datos, lo digo. No ejecuto acciones, solo recomiendo.').trim();

const LLM_SQL     = env.get('LLM_MODEL')         || 'qwen2.5-coder:14b';
const LLM_SUMMARY = env.get('LLM_SUMMARY_MODEL') || 'qwen2.5:14b';

const APP_TZ   = env.get('APP_TZ')        || 'America/Guayaquil';
const APP_OFF  = env.get('APP_TZ_OFFSET') || '-05:00';
const ES_TZ    = env.get('ES_TZ')         || 'Europe/Madrid';
const ES_OFF   = env.get('ES_TZ_OFFSET')  || '+02:00';

// Cosas útiles del runtime
const allowedTables = Array.from(new Set(flow.get('allowed_tables') || []));

const about = {
  name: NAME,
  version: VERSION,
  owner: OWNER,
  mission: MISSION,
  tone: TONE,
  safeguards: [GUARDS],
  models: { sql_generator: LLM_SQL, summarizer: LLM_SUMMARY },
  timezone: { app: APP_TZ, offset: APP_OFF, alt: { es: ES_TZ, offset: ES_OFF } },
  data: { tables_allowed: allowedTables },
  endpoints: [
    { method:'POST', path:'/ask',    body:'{ question: "…" }' },
    { method:'GET',  path:'/about' }
  ],
  samples: [
    'about',
    '¿quién eres?',
    '¿Qué pasó con la AH desde las 09:00 a 10:00 del 21/03/2025?',
    'Sugerencias ahora',
    'Tendencia T+RH últimas 50 lecturas'
  ]
};

msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = { ok:true, about, now: new Date().toISOString() };
return msg;

// ask_entry
// - lee msg.payload.question (string)
// - si falta, devuelve error estructurado
// - si la pregunta es "quién eres / qué puedes hacer / about",
//   responde directamente sin pasar por SQL.

let q = '';

// 1) Extraer la pregunta
if (msg.payload && typeof msg.payload === 'object' && msg.payload.question) {
    q = String(msg.payload.question).trim();
} else if (typeof msg.payload === 'string') {
    // alternativa: permitir que el body sea un string puro
    q = msg.payload.trim();
}

// 2) Si no hay pregunta, error
if (!q) {
    msg.payload = {
        answer: '❌ Falta el campo "question" en el cuerpo del POST /ask.',
        columns: [],
        rows: [],
        sql: '',
        via: 'web',
        suggestions: [
            'Ejemplo: {"question":"¿Cuántos registros hay hoy?"}'
        ]
    };
    // salida 2 -> http response
    return [null, msg];
}

// 3) Determinar vía (web / telegram / etc.)
if (msg.payload && typeof msg.payload === 'object' && msg.payload.via) {
    msg.via = String(msg.payload.via);
} else {
    msg.via = msg.via || 'web';
}

// 4) Normalizar pregunta para detectar intent "ABOUT"
const qNorm = q
    .toLowerCase()
    .normalize('NFD')                // quita acentos
    .replace(/[\u0300-\u036f]/g, ''); 

const isAbout =
    /quien eres\??/.test(qNorm) ||
    /qu[eé] eres\??/.test(qNorm) ||
    /que puedes hacer\??/.test(qNorm) ||
    /ayuda/.test(qNorm) ||
    /\babout\b/.test(qNorm) ||
    /\bwho are you\b/.test(qNorm) ||          
    /\bwhat can you do\b/.test(qNorm) ||      
    /\bhelp\b/.test(qNorm);                   

// 4.1) Detectar idioma del usuario (heurística simple)
function detectLang(text) {
  const t = (text || '').toLowerCase();

  // Señales fuertes de español
  const hasEsChars = /[áéíóúñ¿¡]/.test(t);
  const esHits = (t.match(/\b(el|la|los|las|de|que|como|cómo|hoy|ayer|últim[oa]s?|promedio|temperatura|humedad|luz)\b/g) || []).length;

  // Señales fuertes de inglés
    const enHits = (t.match(/\b(the|what|how|who|are|you|help|about|today|yesterday|last|average|temperature|humidity|light)\b/g) || []).length;


  if (hasEsChars || esHits > enHits) return 'es';
  if (enHits > esHits) return 'en';
  return 'es'; // default seguro (tu sistema ya está en español)
}

msg.userLang = detectLang(q);


// 5) Si es pregunta sobre identidad/capacidades, responder directo
if (isAbout) {
    const NAME    = env.get('ABOUT_NAME')    || 'QUILLAMA';
    const VERSION = env.get('ABOUT_VERSION') || '0.1.0';
    const OWNER   = env.get('ABOUT_OWNER')   || 'Quillaqua';

    const lang = (msg.userLang || 'es').toLowerCase();

    const MISSION = (env.get('ABOUT_MISSION') || 
        'Analista de clima para invernaderos: leo la tabla de lecturas, ' +
        'resumo el estado, detecto tendencias y sugiero acciones.'
    ).trim();

    const TONE = (env.get('ABOUT_TONE') || 
        'Claro, breve y accionable.'
    ).trim();

    msg.payload = {
        answer: (lang === 'en')
            ? `I'm ${NAME}, a data assistant for your greenhouse.

            • Version: ${VERSION}
            • Owner: ${OWNER}
            • Mission: ${MISSION}

            I read climate and actuator data from the database (table "lecturas"),
            turn your questions into safe SQL queries, and explain the results in plain language.

            I don't control the hardware directly: I only provide recommendations based on the data.
            My style is: ${TONE}`
                    : `Soy ${NAME}, un asistente de datos para tu invernadero.

            • Versión: ${VERSION}
            • Propietario: ${OWNER}
            • Misión: ${MISSION}

            Trabajo leyendo los datos de clima y actuadores en la base de datos (tabla "lecturas"),
            convierto tus preguntas en consultas SQL seguras y te explico los resultados en lenguaje natural.

            No controlo directamente el hardware: solo te doy recomendaciones basadas en los datos.
            Mi estilo es: ${TONE}`,

        columns: [],
        rows: [],
        sql: '',          // aquí no hay SQL real
        via: msg.via,
        suggestions: [
            'Promedio de T en los últimos 30 min',
            'Tendencia de T y RH en las últimas 50 lecturas',
            '¿Cómo ha estado el VPD en la última hora?',
            '¿Qué actuadores se activaron más veces hoy?'
        ]
    };

    // salida 2 -> respuesta HTTP directa
    return [null, msg];
}

// 6) Caso normal: guardar para pasos siguientes y seguir al flujo NL→SQL
msg.userQuestion = q;
return [msg, null];

// Empaqueta la respuesta final para la UI / Telegram

let content = '';

if (msg.payload && msg.payload.message && typeof msg.payload.message.content === 'string') {
    content = msg.payload.message.content;
} else if (typeof msg.payload === 'string') {
    content = msg.payload;
}

const answer = (content || '').trim() || 'Sin respuesta de la IA.';

const rows = msg.rows || [];
const columns = msg.columns || [];
const sql = msg.sql || msg.topic || '';

msg.payload = {
    answer: answer,
    columns: columns,
    rows: rows,
    sql: sql,
    via: msg.via || 'web',
    suggestions: [] // de momento vacío; la UI puede generar sugerencias
    // quillama: null
};

return msg;

// Recibe respuesta de Ollama y deja en msg.sql una única sentencia SELECT segura.
// En caso de problema, construye respuesta de error y sale por la salida 2.

function fail(reason, sqlText) {
    msg.payload = {
        answer: '❌ No pude generar una consulta SQL segura: ' + reason,
        columns: [],
        rows: [],
        sql: sqlText || '',
        via: msg.via || 'web',
        suggestions: [
            'Reformula la pregunta con más detalle.',
            'Pide ver directamente la consulta SQL.'
        ]
    };
    return [null, msg]; // salida 2 -> http response
}

let content = '';

if (msg.payload && msg.payload.message && typeof msg.payload.message.content === 'string') {
    content = msg.payload.message.content;
} else if (typeof msg.payload === 'string') {
    content = msg.payload;
}

if (!content) {
    return fail('respuesta vacía del modelo.', '');
}

// quitar fences markdown
let sql = content.replace(/```sql/gi, '')
                 .replace(/```/g, '')
                 .trim();

// compactar espacios
sql = sql.replace(/\s+/g, ' ').trim();

// 🔧 Parche seguro para la luz:
// La base NO tiene una columna 'Luz', pero sí 'L' para la luz del invernadero.
// Si el modelo usa "Luz" como identificador, lo corregimos a "L".
sql = sql.replace(/\bLuz\b/gi, 'L');

if (!sql) {
    return fail('respuesta vacía tras limpieza.', '');
}

if (!/^select\b/i.test(sql)) {
    return fail('la consulta no comienza con SELECT.', sql);
}

// separar por ';'
const statements = sql.split(';').map(s => s.trim()).filter(Boolean);
if (statements.length !== 1) {
    return fail('se detectaron varias sentencias; solo se permite una.', sql);
}

// bloquear palabras peligrosas
const forbidden = /\b(INSERT|UPDATE|DELETE|DROP|TRUNCATE|CREATE|ALTER|GRANT|REVOKE)\b/i;
if (forbidden.test(sql)) {
    return fail('se detectaron palabras SQL peligrosas (INSERT/UPDATE/DELETE, etc.).', sql);
}

// SQL válida
msg.sql = sql;
msg.topic = sql; // para el nodo mysql

return [msg, null];

const rows = msg.payload || [];

// 1) agrupar columnas por tabla
const byTable = {};
for (const r of rows) {
    const t = r.TABLE_NAME;
    if (!byTable[t]) byTable[t] = [];
    byTable[t].push({
        name: r.COLUMN_NAME,
        type: r.DATA_TYPE
    });
}

// 2) construir texto de esquema para el LLM
let lines = [];
lines.push("Esquema de la base de datos QDB:");
for (const table of Object.keys(byTable).sort()) {
    lines.push(`\nTabla ${table}:`);
    for (const col of byTable[table]) {
        lines.push(`- ${col.name} (${col.type})`);
    }
}

// guardar esquema en contexto global
const schemaText = lines.join("\n");
global.set("dbSchema", schemaText);

// 3) mantener tu lógica de allowed_tables
const present = new Set(rows.map(r => r.TABLE_NAME));
const strict = new Set(flow.get("allowed_tables") || [
  "lecturas","actuators","nutrient_readings","system_events",
  "v_current_status","v_last_24h","v_alarms","v_energy_security"
]);
flow.set("allowed_tables", [...[...strict].filter(t => present.has(t))]);

// opcional: mostrar algo de estado en el nodo
node.status({ text: "Esquema: " + Array.from(present).join(", ") });

// dejamos pasar msg para que debug vea las filas si quieres
return msg;

const DB = env.get('DB_NAME') || 'QDB';
msg.topic = `SELECT TABLE_NAME, COLUMN_NAME, DATA_TYPE
             FROM information_schema.COLUMNS
             WHERE TABLE_SCHEMA = '${DB}'
             ORDER BY TABLE_NAME, ORDINAL_POSITION;`;
return msg;

const rows = Array.isArray(msg.payload) ? msg.payload : [];
const sql = msg.sql || msg.topic || '';
const question = msg.userQuestion || '';

const columns = rows.length ? Object.keys(rows[0]) : [];
msg.rows = rows;
msg.columns = columns;

const MAX_ROWS_PREVIEW = 50;
const previewRows = rows.slice(0, MAX_ROWS_PREVIEW);

msg.headers = { 'Content-Type': 'application/json' };

// 👇 idioma (debe venir seteado antes, idealmente desde ask_entry)
const lang = (msg.userLang || 'es').toLowerCase();

const systemPrompt = (lang === 'en')
    ? `You are a data assistant who explains SQL query results to non-technical users.

Instructions:
- ALWAYS respond in English.
- Be direct: explain what the values mean (average, min, max, and whether it goes up, down, or stays stable).
- Do not talk about data formats (JSON, rows, records, columns, etc.) unless the user explicitly asks.
- If you see columns like vpd_min, vpd_max, vpd_avg (or similar), summarize the range and say if it looks stable or variable.
- If there is only one average value (e.g., clima_avg_today, light_avg_today, temp_avg_last_hour), give a short explanation of that value.
- If the result is empty, simply say no data was found for the requested period.`
    : `Eres un asistente de datos que explica resultados de consultas SQL a usuarios no técnicos.

Instrucciones:
- Responde SIEMPRE en español neutro.
- Ve directo al punto: explica qué significan los valores (promedio, mínimo, máximo, si sube, baja o se mantiene estable).
- No hables del formato de los datos (JSON, filas, registros, columnas, etc.) salvo que el usuario lo pida explícitamente.
- Si ves columnas como vpd_min, vpd_max, vpd_prom (o similares), resume el rango y comenta si parece estable o variable.
- Si solo viene un valor promedio (por ejemplo clima_prom_hoy, luz_promedio_hoy, temperatura_promedio_ultima_hora), da una respuesta corta explicando ese valor.
- Si el resultado está vacío, simplemente indica que no se encontraron datos en el periodo solicitado.`;

const userBlock = (lang === 'en')
    ? `Original user question:
${question}

Executed SQL query:
${sql}

First ${previewRows.length} results in JSON:
${JSON.stringify(previewRows, null, 2)}

Total rows: ${rows.length}`
    : `Pregunta original del usuario:
${question}

Consulta SQL ejecutada:
${sql}

Primeros ${previewRows.length} resultados en JSON:
${JSON.stringify(previewRows, null, 2)}

Número total de filas: ${rows.length}`;

msg.payload = {
    model: 'qwen2.5:14b',
    stream: false,
    options: {
        temperature: 0,     // 👈 ayuda a “obedecer” más el idioma
        num_ctx: 1024,
        num_predict: 220
    },
    messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userBlock }
    ]
};

return msg;

// Guarda el contenido de lecturas_sinonimos.txt en global.dbSchema

const txt = typeof msg.payload === 'string' ? msg.payload : '';

global.set('dbSchema', txt);

node.status({ text: txt ? 'dbSchema cargado' : 'vacío' });

return null;

// Guarda el contenido del archivo en global.sqlExamples

const txt = typeof msg.payload === 'string' ? msg.payload : '';

global.set('sqlExamples', txt);

node.status({ text: txt ? 'SQL examples cargados' : 'vacío' });

return null;
